export const PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Teletorch</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{background:#000;color:#fff;font-family:Consolas,\"Courier New\",Courier,monospace;min-height:100vh;user-select:none}\nbody{display:flex;flex-direction:column;align-items:center;padding:8px 4px 16px}\n\n/* TV screen: exact 40-col monospace grid */\n#screen-wrap{\n  position:relative;\n  background:#000;\n  border:1px solid #333;\n  overflow:hidden;\n  cursor:crosshair;\n  /* width set by JS */\n}\n#screen{\n  display:block;\n  white-space:pre;\n  line-height:1.15;\n  /* font-size and width set by JS */\n}\n/* Each row span */\n.row{\n  display:block;\n  white-space:pre;\n  overflow:hidden;\n  font-family:inherit;\n  font-size:inherit;\n  line-height:inherit;\n  font-style:normal;\n}\n\n/* Title band: row index 1 -- blue BG, yellow text */\n.row-title{\n  background:#0000C8;\n  display:block;\n}\n\n/* Fastext row: row index 23 -- coloured labels */\n.row-fastext .ft-red    { color:#f00 }\n.row-fastext .ft-green  { color:#0f0 }\n.row-fastext .ft-yellow { color:#ff0 }\n.row-fastext .ft-cyan   { color:#0ff }\n.row-fastext .ft-white  { color:#fff }\n\n/* Torch overlay */\n#torch-overlay{\n  position:absolute;inset:0;\n  pointer-events:none;\n  display:none;\n  z-index:5;\n}\nbody.torch-on #torch-overlay{display:block}\n\n/* Colour classes for normal rows */\n.c-white   {color:#fff}\n.c-yellow  {color:#ff0}\n.c-cyan    {color:#0ff}\n.c-green   {color:#0f0}\n.c-red     {color:#f00}\n.c-magenta {color:#f0f}\n.c-blue    {color:#4d7cff}\n.c-title   {color:#ff0}  /* yellow text on blue BG */\n\n/* Controls below the screen */\n#controls{\n  margin-top:6px;\n  display:flex;\n  flex-direction:column;\n  gap:6px;\n  /* width matched to screen-wrap by JS */\n}\n\n/* Digit display */\n#digit-display{\n  font-size:clamp(16px,3.5vw,32px);\n  color:#ff0;\n  letter-spacing:4px;\n  text-align:center;\n  border-bottom:2px solid #ff0;\n  padding:2px 0;\n  min-width:4ch;\n  display:inline-block;\n}\n#digit-label{\n  color:#888;\n  font-size:clamp(9px,1.4vw,12px);\n  margin-right:6px;\n  display:inline;\n}\n#digit-row{\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  gap:8px;\n}\n\n/* Fastext buttons row */\n#fastext-row{\n  display:flex;\n  gap:4px;\n}\n.fbtn{\n  flex:1;\n  padding:5px 2px;\n  background:#111;\n  border:none;\n  cursor:pointer;\n  font-family:inherit;\n  font-size:clamp(9px,1.6vw,13px);\n  text-align:center;\n  font-style:normal;\n  font-weight:bold;\n  color:#000;\n}\n.fbtn:hover{filter:brightness(1.2)}\n.fbtn:active{filter:brightness(0.7)}\n.fbtn-red    {background:#f00}\n.fbtn-green  {background:#0f0}\n.fbtn-yellow {background:#ff0}\n.fbtn-cyan   {background:#0ff}\n\n/* Keypad */\n#keypad-area{\n  display:flex;\n  gap:8px;\n  align-items:flex-start;\n  flex-wrap:wrap;\n}\n#keypad{\n  display:grid;\n  gap:3px;\n}\n/* desktop: 1 row of 11 buttons */\n#keypad.kp-wide{\n  grid-template-columns:repeat(11,1fr);\n}\n/* mobile: 4x3 grid */\n#keypad.kp-narrow{\n  grid-template-columns:repeat(3,1fr);\n}\n.kbtn{\n  background:#111;color:#fff;border:1px solid #555;\n  padding:5px 0;\n  cursor:pointer;font-family:inherit;\n  font-size:clamp(11px,1.8vw,15px);\n  text-align:center;\n  min-width:28px;\n}\n.kbtn:hover{background:#333}\n.kbtn:active{background:#555}\n.kbtn-back{color:#ff0;border-color:#ff0}\n.kbtn-back:hover{background:#332200}\n\n/* Sub-page arrows */\n#subpage-btns{\n  display:flex;flex-direction:column;gap:3px;\n}\n.spbtn{\n  background:#111;color:#fff;border:1px solid #555;\n  padding:5px 8px;cursor:pointer;font-family:inherit;\n  font-size:clamp(11px,1.8vw,14px);\n}\n.spbtn:hover{background:#333}\n\n/* Place bar */\n#place-bar{\n  display:flex;\n  gap:5px;\n  align-items:center;\n  flex-wrap:wrap;\n}\n#place-bar label{color:#0ff;font-size:clamp(10px,1.6vw,13px)}\n#place-input{\n  flex:1;min-width:100px;\n  background:#111;color:#fff;border:1px solid #444;\n  padding:4px 5px;font-family:inherit;\n  font-size:clamp(10px,1.6vw,13px);\n}\n#place-input:focus{outline:1px solid #0ff}\n#place-btn{\n  background:#111;color:#0ff;border:1px solid #0ff;\n  padding:4px 8px;cursor:pointer;font-family:inherit;\n  font-size:clamp(10px,1.6vw,13px);\n}\n#place-btn:hover{background:#0ff;color:#000}\n#place-name{color:#0f0;font-size:clamp(9px,1.4vw,12px);min-width:60px}\n\n/* Torch row */\n#torch-row{\n  display:flex;align-items:center;gap:6px;\n}\n#torch-label{color:#888;font-size:clamp(9px,1.4vw,12px)}\n#torch-btn{\n  background:#111;color:#888;border:1px solid #444;\n  padding:3px 8px;cursor:pointer;font-family:inherit;\n  font-size:clamp(9px,1.4vw,12px);\n}\nbody.torch-on #torch-btn{color:#ff0;border-color:#ff0}\n\n/* Footer */\n#footer{\n  margin-top:6px;\n  color:#555;\n  font-size:clamp(8px,1.2vw,10px);\n  text-align:center;\n}\n#footer a{color:#4d7cff;text-decoration:none}\n#footer a:hover{text-decoration:underline}\n\n/* Aria-live hidden text */\n#a11y-text{\n  position:absolute;\n  width:1px;height:1px;\n  overflow:hidden;clip:rect(0,0,0,0);\n  white-space:pre;\n}\n</style>\n</head>\n<body>\n\n<div id=\"screen-wrap\" tabindex=\"0\" aria-label=\"Teletext screen\" role=\"region\">\n  <div id=\"screen\" aria-hidden=\"true\"></div>\n  <canvas id=\"torch-overlay\" aria-hidden=\"true\"></canvas>\n</div>\n\n<div id=\"controls\">\n  <div id=\"fastext-row\" role=\"group\" aria-label=\"Fastext quick links\">\n    <button class=\"fbtn fbtn-red\"    id=\"ft-red\"    aria-label=\"Red fastext\">---</button>\n    <button class=\"fbtn fbtn-green\"  id=\"ft-green\"  aria-label=\"Green fastext\">---</button>\n    <button class=\"fbtn fbtn-yellow\" id=\"ft-yellow\" aria-label=\"Yellow fastext\">---</button>\n    <button class=\"fbtn fbtn-cyan\"   id=\"ft-cyan\"   aria-label=\"Cyan fastext\">---</button>\n  </div>\n\n  <div id=\"keypad-area\">\n    <div>\n      <div id=\"digit-row\">\n        <span id=\"digit-label\">P</span>\n        <div id=\"digit-display\" aria-live=\"polite\" aria-label=\"Page number being typed\">___</div>\n      </div>\n    </div>\n    <div id=\"keypad\" class=\"kp-wide\" role=\"group\" aria-label=\"Page number keypad\">\n      <button class=\"kbtn\" data-d=\"1\" aria-label=\"1\">1</button>\n      <button class=\"kbtn\" data-d=\"2\" aria-label=\"2\">2</button>\n      <button class=\"kbtn\" data-d=\"3\" aria-label=\"3\">3</button>\n      <button class=\"kbtn\" data-d=\"4\" aria-label=\"4\">4</button>\n      <button class=\"kbtn\" data-d=\"5\" aria-label=\"5\">5</button>\n      <button class=\"kbtn\" data-d=\"6\" aria-label=\"6\">6</button>\n      <button class=\"kbtn\" data-d=\"7\" aria-label=\"7\">7</button>\n      <button class=\"kbtn\" data-d=\"8\" aria-label=\"8\">8</button>\n      <button class=\"kbtn\" data-d=\"9\" aria-label=\"9\">9</button>\n      <button class=\"kbtn\" data-d=\"0\" aria-label=\"0\">0</button>\n      <button class=\"kbtn kbtn-back\" id=\"btn-back\" aria-label=\"Back/clear\">Bk</button>\n    </div>\n    <div id=\"subpage-btns\" aria-label=\"Sub-page navigation\">\n      <button class=\"spbtn\" id=\"btn-prev\" aria-label=\"Previous sub-page\">&lt; Prev</button>\n      <button class=\"spbtn\" id=\"btn-next\" aria-label=\"Next sub-page\">Next &gt;</button>\n    </div>\n  </div>\n\n  <div id=\"place-bar\">\n    <label for=\"place-input\">Place:</label>\n    <input id=\"place-input\" type=\"text\" placeholder=\"City or lat,lon\" autocomplete=\"off\" aria-label=\"Set place\">\n    <button id=\"place-btn\" aria-label=\"Set place\">Set</button>\n    <span id=\"place-name\" aria-live=\"polite\"></span>\n  </div>\n\n  <div id=\"torch-row\">\n    <span id=\"torch-label\">Torch:</span>\n    <button id=\"torch-btn\" aria-pressed=\"false\" aria-label=\"Toggle torch mode\">Off</button>\n  </div>\n</div>\n\n<div id=\"footer\">\n  Data: USGS, NASA EONET, Open-Meteo (<a href=\"/p/199\" target=\"_blank\">CC BY 4.0</a>).\n  Text: <a href=\"/p/100.txt\">/p/100.txt</a>\n</div>\n\n<pre id=\"a11y-text\" aria-live=\"polite\" aria-atomic=\"true\"></pre>\n\n<script>\n(function(){\n'use strict';\n\n// ---------------------------------------------------------------------------\n// State\n// ---------------------------------------------------------------------------\nvar curPage   = 100;\nvar curSub    = 1;\nvar curSubs   = 1;\nvar curLinks  = [];\nvar digits    = '';\nvar torchOn   = false;\nvar torchRow  = 12;\nvar fetchCtrl = null;\n\n// ---------------------------------------------------------------------------\n// Colour map\n// ---------------------------------------------------------------------------\nvar COL = {\n  white:   '#ffffff',\n  yellow:  '#ffff00',\n  cyan:    '#00ffff',\n  green:   '#00ff00',\n  red:     '#ff0000',\n  magenta: '#ff00ff',\n  blue:    '#4d7cff',\n  title:   '#ffff00'   // yellow text, but row gets blue BG via row-title class\n};\n\n// ---------------------------------------------------------------------------\n// DOM refs\n// ---------------------------------------------------------------------------\nvar screen      = document.getElementById('screen');\nvar overlay     = document.getElementById('torch-overlay');\nvar digitDisp   = document.getElementById('digit-display');\nvar placeInput  = document.getElementById('place-input');\nvar placeBtn    = document.getElementById('place-btn');\nvar placeName   = document.getElementById('place-name');\nvar torchBtn    = document.getElementById('torch-btn');\nvar a11yText    = document.getElementById('a11y-text');\nvar screenWrap  = document.getElementById('screen-wrap');\nvar controls    = document.getElementById('controls');\nvar keypad      = document.getElementById('keypad');\nvar ftBtns      = {\n  red:    document.getElementById('ft-red'),\n  green:  document.getElementById('ft-green'),\n  yellow: document.getElementById('ft-yellow'),\n  cyan:   document.getElementById('ft-cyan')\n};\n\n// ---------------------------------------------------------------------------\n// Build the 24 row divs once\n// ---------------------------------------------------------------------------\nvar rowDivs = [];\nfor (var i = 0; i < 24; i++) {\n  var d = document.createElement('div');\n  d.className = 'row';\n  screen.appendChild(d);\n  rowDivs.push(d);\n}\n\n// ---------------------------------------------------------------------------\n// Font sizing: measure actual char width then scale to fill screen\n// ---------------------------------------------------------------------------\nvar measureSpan = document.createElement('span');\nmeasureSpan.style.cssText = 'position:absolute;visibility:hidden;white-space:pre;font-family:Consolas,\"Courier New\",Courier,monospace;font-size:100px';\nmeasureSpan.textContent = '0'.repeat(40);\ndocument.body.appendChild(measureSpan);\n\nfunction computeScreenWidth() {\n  // Screen width = min(1000px, 94vw, (innerHeight - 230px) * 4/3)\n  var vw94 = window.innerWidth * 0.94;\n  var fromH = (window.innerHeight - 230) * (4 / 3);\n  return Math.max(200, Math.min(1000, Math.min(vw94, fromH)));\n}\n\nfunction syncLayout() {\n  var sw = computeScreenWidth();\n  screenWrap.style.width = sw + 'px';\n  controls.style.width = sw + 'px';\n\n  // Measure: how wide is a 40-char string at 100px?\n  measureSpan.style.fontSize = '100px';\n  var charW100 = measureSpan.offsetWidth / 40;\n  // Target: 40 chars fill sw px\n  var fs = sw / (charW100 / 100);   // fs = sw * 100 / charW100\n  // Clamp to reasonable range\n  fs = Math.max(6, Math.min(40, fs));\n  screen.style.fontSize = fs + 'px';\n\n  // Screen height = 24 lines * lineHeight\n  var lh = fs * 1.15;\n  screenWrap.style.height = Math.ceil(24 * lh) + 'px';\n\n  // Keypad layout: wide if > 600px, narrow otherwise\n  if (sw >= 560) {\n    keypad.className = 'kp-wide';\n  } else {\n    keypad.className = 'kp-narrow';\n  }\n\n  // Canvas sync\n  overlay.width  = screenWrap.offsetWidth;\n  overlay.height = screenWrap.offsetHeight;\n}\n\n// ---------------------------------------------------------------------------\n// Render page data into the screen\n// ---------------------------------------------------------------------------\n\n// Parse fastext row (row 23) into coloured spans.\n// Each 10-char slot maps to a colour.\nfunction renderFastextRow(text, links) {\n  var rowEl = rowDivs[23];\n  rowEl.className = 'row row-fastext';\n  rowEl.innerHTML = '';\n\n  // Build a map: slot index -> colour\n  var slotColors = ['white', 'white', 'white', 'white'];\n  var colorOrder = ['red', 'green', 'yellow', 'cyan'];\n  for (var i = 0; i < links.length; i++) {\n    var idx = colorOrder.indexOf(links[i].color);\n    if (idx !== -1) slotColors[idx] = links[i].color;\n  }\n\n  for (var s = 0; s < 4; s++) {\n    var chunk = (text || '').slice(s * 10, s * 10 + 10);\n    if (chunk.length < 10) chunk = chunk + ' '.repeat(10 - chunk.length);\n    var sp = document.createElement('span');\n    sp.className = 'ft-' + slotColors[s];\n    sp.textContent = chunk;\n    rowEl.appendChild(sp);\n  }\n}\n\nfunction renderPage(data) {\n  var rows   = data.rows   || [];\n  var colors = data.colors || [];\n  curLinks = data.links || [];\n  curSubs  = data.subs  || 1;\n  curSub   = data.sub   || 1;\n\n  var plainText = '';\n  for (var i = 0; i < 24; i++) {\n    var text  = rows[i]   || '                                        ';\n    var color = colors[i] || 'white';\n\n    if (i === 23) {\n      // Fastext row: multi-colour spans\n      renderFastextRow(text, curLinks);\n    } else if (i === 1 || color === 'title') {\n      // Title band: blue BG, yellow text\n      rowDivs[i].className = 'row row-title c-title';\n      rowDivs[i].textContent = text;\n    } else {\n      var col = COL[color] || '#ffffff';\n      rowDivs[i].className = 'row';\n      rowDivs[i].style.color = col;\n      rowDivs[i].textContent = text;\n    }\n\n    plainText += text + '\\n';\n  }\n\n  // Aria-live text\n  a11yText.textContent = (data.title || '') + '\\n' + plainText;\n\n  // Fastext button labels\n  var colorOrder = ['red','green','yellow','cyan'];\n  colorOrder.forEach(function(c){ ftBtns[c].textContent = '---'; ftBtns[c].dataset.num = ''; });\n  curLinks.forEach(function(lk){\n    if (ftBtns[lk.color]) {\n      ftBtns[lk.color].textContent = lk.num + ' ' + (lk.label || '');\n      ftBtns[lk.color].dataset.num = lk.num;\n    }\n  });\n\n  if (data.placeName) placeName.textContent = data.placeName;\n\n  drawTorch();\n}\n\n// ---------------------------------------------------------------------------\n// Fetch a page\n// ---------------------------------------------------------------------------\nfunction loadPage(num, sub, extra) {\n  sub   = sub   || 1;\n  extra = extra || '';\n  if (fetchCtrl) fetchCtrl.abort();\n  fetchCtrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;\n\n  var url = '/p/' + String(num).padStart(3,'0') + '.json?s=' + sub + extra;\n  var opts = { credentials: 'include' };\n  if (fetchCtrl) opts.signal = fetchCtrl.signal;\n\n  fetch(url, opts)\n    .then(function(r){ return r.json(); })\n    .then(function(data){\n      curPage = num;\n      curSub  = sub;\n      curSubs = data.subs || 1;\n      renderPage(data);\n      var histUrl = '/p/' + String(num).padStart(3,'0') + (sub > 1 ? '?s=' + sub : '');\n      if (window.location.pathname !== '/p/' + String(num).padStart(3,'0')) {\n        history.pushState({ num:num, sub:sub }, '', histUrl);\n      }\n    })\n    .catch(function(e){\n      if (e && e.name === 'AbortError') return;\n      showError('Failed to load page ' + num);\n    });\n}\n\nfunction showError(msg) {\n  var blank = '                                        ';\n  for (var i = 0; i < 24; i++) {\n    rowDivs[i].className = 'row';\n    rowDivs[i].style.color = '#ffffff';\n    rowDivs[i].textContent = blank;\n  }\n  rowDivs[1].className = 'row row-title c-title';\n  rowDivs[1].textContent = 'ERROR                                   ';\n  rowDivs[3].style.color = '#ff0000';\n  rowDivs[3].textContent = (msg + blank).slice(0, 40);\n  a11yText.textContent = 'Error: ' + msg;\n}\n\n// ---------------------------------------------------------------------------\n// Digit entry\n// ---------------------------------------------------------------------------\nfunction pushDigit(d) {\n  if (digits.length >= 3) digits = '';\n  digits += d;\n  var disp = digits + '___';\n  digitDisp.textContent = disp.slice(0, 3);\n  if (digits.length === 3) {\n    var num = parseInt(digits, 10);\n    digits = '';\n    digitDisp.textContent = '___';\n    loadPage(num, 1);\n  }\n}\n\nfunction clearDigits() {\n  digits = '';\n  digitDisp.textContent = '___';\n}\n\n// ---------------------------------------------------------------------------\n// Keyboard\n// ---------------------------------------------------------------------------\ndocument.addEventListener('keydown', function(e) {\n  if (document.activeElement === placeInput) return;\n\n  if (e.key >= '0' && e.key <= '9') { e.preventDefault(); pushDigit(e.key); return; }\n  if (e.key === 'Backspace') { e.preventDefault(); clearDigits(); return; }\n  if (e.key === 'ArrowRight' || e.key === 'PageDown') {\n    e.preventDefault();\n    if (curSub < curSubs) loadPage(curPage, curSub + 1);\n    return;\n  }\n  if (e.key === 'ArrowLeft' || e.key === 'PageUp') {\n    e.preventDefault();\n    if (curSub > 1) loadPage(curPage, curSub - 1);\n    return;\n  }\n  if (e.key === 'F1' || e.key === 'r') { e.preventDefault(); fastextGo('red');    return; }\n  if (e.key === 'F2' || e.key === 'g') { e.preventDefault(); fastextGo('green');  return; }\n  if (e.key === 'F3' || e.key === 'y') { e.preventDefault(); fastextGo('yellow'); return; }\n  if (e.key === 'F4' || e.key === 'c') { e.preventDefault(); fastextGo('cyan');   return; }\n  if (torchOn) {\n    if (e.key === 'ArrowUp')   { e.preventDefault(); torchRow = Math.max(0,  torchRow - 1); drawTorch(); return; }\n    if (e.key === 'ArrowDown') { e.preventDefault(); torchRow = Math.min(23, torchRow + 1); drawTorch(); return; }\n  }\n});\n\nfunction fastextGo(color) {\n  var btn = ftBtns[color];\n  if (btn && btn.dataset.num) loadPage(parseInt(btn.dataset.num, 10), 1);\n}\n\n// ---------------------------------------------------------------------------\n// Keypad buttons\n// ---------------------------------------------------------------------------\ndocument.getElementById('keypad').addEventListener('click', function(e) {\n  var btn = e.target.closest('.kbtn');\n  if (!btn) return;\n  var d = btn.dataset.d;\n  if (d !== undefined) { pushDigit(d); return; }\n  if (btn.id === 'btn-back') { clearDigits(); return; }\n});\n\ndocument.getElementById('btn-prev').addEventListener('click', function(){\n  if (curSub > 1) loadPage(curPage, curSub - 1);\n});\ndocument.getElementById('btn-next').addEventListener('click', function(){\n  if (curSub < curSubs) loadPage(curPage, curSub + 1);\n});\n\n['red','green','yellow','cyan'].forEach(function(c){\n  ftBtns[c].addEventListener('click', function(){ fastextGo(c); });\n});\n\n// ---------------------------------------------------------------------------\n// Place\n// ---------------------------------------------------------------------------\nplaceBtn.addEventListener('click', setPlace);\nplaceInput.addEventListener('keydown', function(e){ if (e.key === 'Enter') setPlace(); });\n\nfunction setPlace() {\n  var val = placeInput.value.trim();\n  if (!val) return;\n  var isCoord = /^-?\\d+(\\.\\d+)?\\s*,\\s*-?\\d+(\\.\\d+)?$/.test(val);\n  var extra;\n  if (isCoord) {\n    var parts = val.split(',');\n    extra = '&lat=' + encodeURIComponent(parts[0].trim()) + '&lon=' + encodeURIComponent(parts[1].trim());\n  } else {\n    extra = '&place=' + encodeURIComponent(val);\n  }\n  var url = '/p/101.json?s=1' + extra;\n  fetch(url, { credentials: 'include' })\n    .then(function(r){ return r.json(); })\n    .then(function(data){\n      curPage = 101; curSub = 1;\n      renderPage(data);\n      var rows = data.rows || [];\n      for (var i = 0; i < rows.length; i++) {\n        var m = rows[i].match(/^Place:\\s*(.+?)\\s*$/);\n        if (m) { placeName.textContent = m[1].trim(); break; }\n      }\n      history.pushState({ num:101, sub:1 }, '', '/p/101');\n    })\n    .catch(function(){ showError('Could not set place'); });\n}\n\n// ---------------------------------------------------------------------------\n// Torch mode\n// ---------------------------------------------------------------------------\ntorchBtn.addEventListener('click', function(){\n  torchOn = !torchOn;\n  document.body.classList.toggle('torch-on', torchOn);\n  torchBtn.textContent = torchOn ? 'On' : 'Off';\n  torchBtn.setAttribute('aria-pressed', String(torchOn));\n  drawTorch();\n});\n\nscreenWrap.addEventListener('mousemove', function(e){\n  if (!torchOn) return;\n  var rect = screenWrap.getBoundingClientRect();\n  var y = e.clientY - rect.top;\n  torchRow = Math.floor((y / rect.height) * 24);\n  torchRow = Math.max(0, Math.min(23, torchRow));\n  drawTorch();\n});\nscreenWrap.addEventListener('touchmove', function(e){\n  if (!torchOn) return;\n  e.preventDefault();\n  var rect = screenWrap.getBoundingClientRect();\n  var y = e.touches[0].clientY - rect.top;\n  torchRow = Math.floor((y / rect.height) * 24);\n  torchRow = Math.max(0, Math.min(23, torchRow));\n  drawTorch();\n}, { passive: false });\n\nfunction drawTorch() {\n  if (!torchOn) {\n    rowDivs.forEach(function(r){ r.style.opacity = ''; });\n    return;\n  }\n  for (var i = 0; i < 24; i++) {\n    var inBeam = (i >= torchRow - 1 && i <= torchRow + 1);\n    rowDivs[i].style.opacity = inBeam ? '1' : '0.2';\n  }\n}\n\n// ---------------------------------------------------------------------------\n// Browser back/forward\n// ---------------------------------------------------------------------------\nwindow.addEventListener('popstate', function(e){\n  if (e.state && e.state.num) {\n    loadPage(e.state.num, e.state.sub || 1);\n  }\n});\n\n// ---------------------------------------------------------------------------\n// Resize\n// ---------------------------------------------------------------------------\nvar resizeTimer;\nwindow.addEventListener('resize', function(){\n  clearTimeout(resizeTimer);\n  resizeTimer = setTimeout(syncLayout, 60);\n});\n\n// ---------------------------------------------------------------------------\n// Initial load\n// ---------------------------------------------------------------------------\n(function init(){\n  syncLayout();\n\n  var m = window.location.pathname.match(/\\/p\\/(\\d{3})/);\n  var initPage = m ? parseInt(m[1], 10) : 100;\n  var initSub  = 1;\n  var sp = new URLSearchParams(window.location.search).get('s');\n  if (sp) initSub = parseInt(sp, 10) || 1;\n\n  var extra = '';\n  var qp = new URLSearchParams(window.location.search);\n  if (qp.get('place')) extra = '&place=' + encodeURIComponent(qp.get('place'));\n  else if (qp.get('lat') && qp.get('lon')) {\n    extra = '&lat=' + encodeURIComponent(qp.get('lat')) + '&lon=' + encodeURIComponent(qp.get('lon'));\n  }\n\n  history.replaceState({ num:initPage, sub:initSub }, '', window.location.href);\n  loadPage(initPage, initSub, extra);\n})();\n\n})();\n</script>\n</body>\n</html>\n";
